function notify(text){$('toast').textContent=text;timeToast=4;$('toast').style.opacity=1}function beep(freq=600,duration=.12){if(!soundOn)return;audioCtx??=new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),v=audioCtx.createGain();o.connect(v);v.connect(audioCtx.destination);o.frequency.value=freq;v.gain.setValueAtTime(.04,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.start();o.stop(audioCtx.currentTime+duration)}function terrainAt(x,z){return z>11.5&&z<16.5?2:Math.abs(x)<16&&z<10&&z>-18?1:0}function setCamo(i){camo=i;skin.color.set(palette[i]);document.querySelectorAll('[data-camo]').forEach(b=>b.classList.toggle('active',+b.dataset.camo===i));beep(500+i*100)}function isBlocked(x,z){return blockers.some(b=>Math.abs(x-b.x)<b.w/2+.33&&Math.abs(z-b.z)<b.d/2+.33)}function lineBlocked(x,z,tx,tz){const d=Math.hypot(tx-x,tz-z);for(let t=.5;t<d;t+=.45){if(isBlocked(x+(tx-x)*t/d,z+(tz-z)*t/d))return true}return false}function distance(o){return Math.hypot(pos.x-o.x,pos.z-o.z)}function useDecoy(){if(!playing||ended)return;if(decoys<=0){notify('诱饵已耗尽');return}decoys--;decoy={x:Math.max(-30,Math.min(30,pos.x-Math.sin(facing)*5)),z:Math.max(-27,Math.min(27,pos.z-Math.cos(facing)*5)),life:7};const pulse=ring(decoy.x,decoy.z,.8,'#e7d392');effects.push({mesh:pulse,life:7,max:7,type:'pulse'});notify('诱饵已投出 · 附近守卫正在调查声源');beep(350,.3)}
function interact(){if(!playing||ended)return;const goal=goals.find(g=>!g.done&&distance(g)<2.1);if(goal){goal.done=true;goal.marker.visible=false;goal.ring.visible=false;$('goal'+goal.label).classList.add('done');const n=goals.filter(g=>g.done).length;$('count').textContent=n+' / 3';notify(n===3?'全部情报已获取 · 返回溪流南侧撤离点':goal.name+' · 完成');beep(900,.3);return}if(!radarOff&&distance(radarNode)<2.2){radarOff=true;radarLamp.material=mat('#a2ee86');$('radarCheck').textContent='✓';notify('监视雷达已关闭 · 探测范围降低');beep(250,.3);return}if(distance(exit)<2.5&&goals.every(g=>g.done)){finish(true);return}const target=guards.find(g=>g.stun<=0&&distance(g)<2.6);if(target){target.stun=9;target.suspicion=0;const tongue=mesh(new THREE.CylinderGeometry(.045,.045,distance(target),6),'#f0a6a1',0,0,0);const start=new THREE.Vector3(pos.x,.7,pos.z),end=new THREE.Vector3(target.x,1,target.z);tongue.position.copy(start.clone().add(end).multiplyScalar(.5));tongue.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),end.sub(start).normalize());effects.push({mesh:tongue,life:.3,max:.3,type:'tongue'});notify('舌击命中 · 守卫眩晕 9 秒');beep(180,.1);return}notify('靠近发光终端后按 E；也可舌击近处守卫')}
function showModal(title,body,eyebrow='FIELD MANUAL'){playing=false;keys.w=keys.a=keys.s=keys.d=keys.shift=false;$('modal').hidden=false;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalEyebrow').textContent=eyebrow;$('resume').hidden=ended}
function manual(){showModal('成为丛林的一部分。','<p>夺取三份情报，再回到溪流南侧的绿色撤离圈。匹配地表颜色、蹲伏与遮挡能显著降低暴露。</p><div class="manual-row"><span>移动 / 疾行 / 蹲伏</span><span>WASD / Shift / C</span></div><div class="manual-row"><span>选择叶绿、沙褐、溪蓝</span><span>1 / 2 / 3</span></div><div class="manual-row"><span>自动匹配当前环境</span><span>Q</span></div><div class="manual-row"><span>收集情报 / 关闭雷达 / 舌击</span><span>E</span></div><div class="manual-row"><span>朝前投出诱饵 · 共 3 次</span><span>F</span></div><p>黄色扇形是守卫视野；警戒升高后会追击。躲到建筑后方可切断视线。疾行会发出声响，溪水会降低移动速度。关闭东北雷达可削弱守卫探测。</p>')}
function finish(win){ended=true;const grade=win?(alerts===0?'S':health>65?'A':'B'):'—';showModal(win?'幽灵已安全归巢。':'行动中断。',`<p>${win?'研究情报已安全带出黑棘营地。丛林没有留下你的踪迹。':'你被营地守卫发现。尝试匹配地表颜色，沿建筑阴影移动，并用诱饵调离守卫。'}</p><div class="manual-row"><span>行动评级</span><b>${grade}</b></div><div class="manual-row"><span>获取情报</span><b>${goals.filter(g=>g.done).length} / 3</b></div><div class="manual-row"><span>行动时间</span><b>${formatTime(elapsed)}</b></div><div class="manual-row"><span>触发警报</span><b>${alerts} 次</b></div><div class="manual-row"><span>雷达压制</span><b>${radarOff?'已完成':'未完成'}</b></div>`,win?'OPERATION COMPLETE':'MISSION FAILED');beep(win?1000:130,.5)}
function reset(){pos.x=-10;pos.z=20;health=stamina=100;decoys=3;decoy=null;radarOff=false;elapsed=alert=alerts=0;lastAlert=false;crouch=false;ended=false;playing=true;setCamo(0);for(const g of goals){g.done=false;g.marker.visible=g.ring.visible=true;$('goal'+g.label).classList.remove('done')}for(const g of guards){g.x=g.route[0][0];g.z=g.route[0][1];g.index=0;g.stun=g.suspicion=0}effects.forEach(e=>scene.remove(e.mesh));effects.length=0;$('count').textContent='0 / 3';$('radarCheck').textContent='◇';radarLamp.material=mat('#f6cb6b');$('modal').hidden=true;notify('重新部署完成 · 先越过木桥进入营地')}
function formatTime(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(e.repeat)return;if(k==='escape'){if(ended)return;if(playing)showModal('行动已暂停。','<p>当前行动已保存于本次游戏，准备好后继续潜入。</p>','OPERATION PAUSED');else{$('modal').hidden=true;playing=true}return}if(k==='?'||k==='h'){manual();return}if(!playing||ended)return;if(k==='c')crouch=!crouch;if(k==='q')setCamo(terrainAt(pos.x,pos.z));if(['1','2','3'].includes(k))setCamo(+k-1);if(k==='e')interact();if(k==='f')useDecoy()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);if(playing&&!ended)showModal('行动已暂停。','<p>回到行动窗口后继续。</p>','OPERATION PAUSED')});window.addEventListener('wheel',e=>{zoom=Math.max(.7,Math.min(1.5,zoom+e.deltaY*.001))},{passive:true});
document.querySelectorAll('[data-camo]').forEach(b=>b.onclick=()=>{if(playing)setCamo(+b.dataset.camo)});$('autoCamo').onclick=()=>{if(playing)setCamo(terrainAt(pos.x,pos.z))};$('decoy').onclick=useDecoy;$('dash').onpointerdown=()=>keys.shift=true;$('dash').onpointerup=$('dash').onpointerleave=()=>keys.shift=false;$('help').onclick=manual;$('pause').onclick=()=>{if(!ended)showModal('行动已暂停。','<p>观察地图，规划下一步路线。</p>','OPERATION PAUSED')};$('resume').onclick=()=>{playing=true;$('modal').hidden=true};$('restart').onclick=reset;$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent='声音 '+(soundOn?'ON':'OFF');beep()};$('touchE').onclick=interact;$('touchC').onclick=()=>crouch=!crouch;document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
const map=$('map').getContext('2d');function mapDraw(){const w=240,h=210,s=3.8,ox=120,oz=105;map.clearRect(0,0,w,h);map.strokeStyle='#88b37415';map.lineWidth=1;for(let i=0;i<240;i+=20){map.beginPath();map.moveTo(i,0);map.lineTo(i,h);map.stroke();map.beginPath();map.moveTo(0,i);map.lineTo(w,i);map.stroke()}map.fillStyle='#94a47922';map.fillRect(ox-16*s,oz-18*s,32*s,28*s);map.fillStyle='#75bbc046';map.fillRect(0,oz+11.5*s,w,5*s);for(const b of blockers){map.fillStyle='#728c6555';map.fillRect(ox+(b.x-b.w/2)*s,oz+(b.z-b.d/2)*s,b.w*s,b.d*s)}for(const g of goals){if(g.done)continue;map.fillStyle='#e6e39e';map.fillRect(ox+g.x*s-3,oz+g.z*s-3,6,6)}for(const g of guards){map.fillStyle=g.stun>0?'#9da193':g.suspicion>40?'#ff7962':'#d3a67e';map.beginPath();map.arc(ox+g.x*s,oz+g.z*s,2.8,0,7);map.fill()}map.strokeStyle='#cdeb87';map.beginPath();map.arc(ox+exit.x*s,oz+exit.z*s,5,0,7);map.stroke();map.fillStyle='#daf8a4';map.beginPath();map.arc(ox+pos.x*s,oz+pos.z*s,3.3,0,7);map.fill();map.strokeStyle='#dcf5aa55';map.beginPath();map.arc(ox+pos.x*s,oz+pos.z*s,7,0,7);map.stroke()}
let last=performance.now();const camTarget=new THREE.Vector3();function tick(now){requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.05);last=now;if(playing&&!ended){elapsed+=dt;const terrain=terrainAt(pos.x,pos.z);let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);const moving=dx!==0||dz!==0,sprint=keys.shift&&moving&&stamina>2&&!crouch;const speed=(crouch?1.8:sprint?6:3.4)*(terrain===2?.65:1);stamina=THREE.MathUtils.clamp(stamina+(sprint?-26:15)*dt,0,100);if(moving){const len=Math.hypot(dx,dz);dx/=len;dz/=len;let nx=THREE.MathUtils.clamp(pos.x+dx*speed*dt,-30,30),nz=THREE.MathUtils.clamp(pos.z+dz*speed*dt,-26,27);if(!isBlocked(nx,pos.z))pos.x=nx;if(!isBlocked(pos.x,nz))pos.z=nz;facing=Math.atan2(-dx,-dz)}noise=sprint?1:0;blend=Math.max(8,Math.min(99,(camo===terrain?94:28)+(crouch?5:0)-(sprint?40:moving?12:0)));player.position.set(pos.x,crouch?-.14:0,pos.z);player.rotation.y=facing;legs.forEach((l,i)=>l.rotation.y=moving?Math.sin(elapsed*speed*6+i*2)*.35:0);playerRing.position.set(pos.x,.12,pos.z);playerRing.material.opacity=.3+Math.sin(elapsed*3)*.1;if(decoy){decoy.life-=dt;if(decoy.life<=0)decoy=null}let highest=0;for(const g of guards){if(g.stun>0){g.stun-=dt;g.g.rotation.z=.7;g.g.children.find(o=>o.geometry?.type==='ShapeGeometry').visible=false;continue}g.g.rotation.z=0;g.g.children.find(o=>o.geometry?.type==='ShapeGeometry').visible=true;const d=distance(g),vx=pos.x-g.x,vz=pos.z-g.z,dot=(Math.sin(g.angle)*vx+Math.cos(g.angle)*vz)/Math.max(d,.001),range=radarOff?6:8;const seen=d<range&&dot>.84&&!lineBlocked(g.x,g.z,pos.x,pos.z);const detected=(seen&&((blend<60)||d<(crouch?2:3.4)))||(noise&&d<5);g.suspicion=THREE.MathUtils.clamp(g.suspicion+(detected?(100-blend)*.75+12:-19)*dt,0,100);highest=Math.max(highest,g.suspicion);let target=g.route[g.index],speed=1.15;if(g.suspicion>65){target=[pos.x,pos.z];speed=2.5;if(d<1.1){health-=24*dt}}else if(decoy&&Math.hypot(decoy.x-g.x,decoy.z-g.z)<13){target=[decoy.x,decoy.z];speed=1.8}const tx=target[0]-g.x,tz=target[1]-g.z,len=Math.hypot(tx,tz);if(len>.35){g.angle=Math.atan2(tx,tz);const nx=g.x+tx/len*speed*dt,nz=g.z+tz/len*speed*dt;if(!isBlocked(nx,g.z))g.x=nx;if(!isBlocked(g.x,nz))g.z=nz}else if(!(decoy&&Math.hypot(decoy.x-g.x,decoy.z-g.z)<13))g.index=(g.index+1)%g.route.length;g.g.position.set(g.x,0,g.z);g.g.rotation.y=g.angle;g.marker.material=mat(g.suspicion>65?'#ff755a':'#eea46a')}alert=highest;if(alert>65&&!lastAlert){alerts++;beep(160,.4);notify('警报 · 切断视线，寻找掩护！')}lastAlert=alert>65;if(health<=0){health=0;finish(false)}radar.rotation.z+=radarOff?0:dt*.5;for(const g of goals){g.marker.rotation.y+=dt;g.marker.position.y=2.4+Math.sin(elapsed*2)*.12}exitRing.material.opacity=goals.every(g=>g.done)?.8+Math.sin(elapsed*3)*.2:.35;for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.type==='pulse'){e.mesh.scale.setScalar(1+((e.max-e.life)%1.5)*3);e.mesh.material.opacity=.7*(1-((e.max-e.life)%1.5)/1.5)}if(e.life<=0){scene.remove(e.mesh);effects.splice(i,1)}}timeToast-=dt;if(timeToast<=0)$('toast').style.opacity=0;let prompt='';if(goals.some(g=>!g.done&&distance(g)<2.1))prompt='E · 获取情报';else if(!radarOff&&distance(radarNode)<2.2)prompt='E · 关闭监视雷达';else if(goals.every(g=>g.done)&&distance(exit)<2.5)prompt='E · 立即撤离';else if(guards.some(g=>g.stun<=0&&distance(g)<2.6))prompt='E · 舌击眩晕';$('interact').style.display=prompt?'block':'none';$('interact').textContent=prompt;$('timer').textContent=formatTime(elapsed);$('status').textContent=alert>65?'已被发现':alert>15?'守卫怀疑':'区域安全';$('status').style.color=alert>65?'#ff967d':alert>15?'#e6cf83':'#c8e5b3';$('blend').textContent=Math.round(blend)+'%';$('blendbar').style.width=blend+'%';$('terrain').textContent=['蕨类植被','营地沙土','溪流浅滩'][terrain];$('stance').textContent=crouch?'蹲伏':sprint?'疾行':'静步';$('healthbar').style.width=health+'%';$('healthtext').textContent='生命体征 '+Math.ceil(health)+'%';$('energy').textContent='体力 '+Math.round(stamina)+'%';$('decoyCount').textContent=decoys+' 次可用';$('coord').textContent='POS '+pos.x.toFixed(1)+' / '+pos.z.toFixed(1);$('exitTask').style.opacity=goals.every(g=>g.done)?1:.5;}
camTarget.set(pos.x,0,pos.z-4);camera.position.lerp(new THREE.Vector3(camTarget.x+15*zoom,29*zoom,camTarget.z+28*zoom),.06);camera.lookAt(camTarget);mapDraw();renderer.render(scene,camera)}camera.position.set(10,32,35);requestAnimationFrame(tick);window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
